import { LitElement, html, css } from 'https://cdn.skypack.dev/lit';

class DmoButton extends LitElement {
  static styles = css`
    button {
      background-color: #6200ea;
      color: white;
      border: none;
      padding: 10px 20px;
      font-size: 16px;
      cursor: pointer;
      border-radius: 5px;
    }
    button:hover {
      background-color: #3700b3;
    }
  `;

  render() {
    return html`<button><slot></slot></button>`;
  }
}

customElements.define('dmo-button', DmoButton);
